export function LabelElement({
  text = "{{text}}",
  control = "{{control}}",
  accent = "{{accent}}",
  showHint = {{showHint}},
}) {
  return (
    <div style={{ width: 300, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12 }}>
      {control === "checkbox" ? (
        <label style={{ display: "flex", alignItems: "center", gap: 8, fontWeight: 600, fontSize: 13, cursor: "pointer" }}>
          <input type="checkbox" style={{ width: 17, height: 17, accentColor: accent }} /> {text}
        </label>
      ) : (
        <div>
          <label htmlFor="lbl-r-input" style={{ display: "block", fontWeight: 600, fontSize: 13, marginBottom: 6, cursor: "pointer" }}>{text}</label>
          <input id="lbl-r-input" type="text" style={{ width: "100%", boxSizing: "border-box", font: "14px system-ui, sans-serif", padding: "9px 11px", borderRadius: 7, border: "1.5px solid #24143035" }} />
        </div>
      )}
      {showHint && <p style={{ margin: "8px 0 0", fontSize: 12, color: "#24143099" }}>Click the label text itself — it focuses the paired control, no JavaScript required.</p>}
    </div>
  );
}
